<?php
namespace Tests\Feature;
use App\Models\{User,Idea};use App\Services\{FormCatalog,AutoAllocator,AccountChallenges};use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\{DB,Queue,Http,Hash};use Illuminate\Support\Str;
class InnovationWorkflowsTest extends \Illuminate\Foundation\Testing\TestCase{
 use RefreshDatabase;
 public function createApplication(){$app=require __DIR__.'/../../bootstrap/app.php';$app->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $app;}
 private function pid():int{return DB::table('programmes')->value('id');}
 private function user(string $role='Evaluator',bool $master=false):User{$u=new User(['name'=>'Jane Private','email'=>uniqid().'@example.test','password'=>'Password-strong-123']);$u->is_master=$master;$u->email_verified_at=now();$u->mfa_confirmed_at=now();$u->onboarding_completed_at=now();$u->save();DB::table('programme_role_user')->insert(['user_id'=>$u->id,'programme_id'=>$this->pid(),'role_id'=>DB::table('roles')->where('name',$role)->value('id')]);return $u->fresh();}
 private function admin():User{$u=$this->user('Programme Administrator',true);$this->actingAs($u)->withSession(['mfa_user_id'=>$u->id,'mfa_verified_at'=>time()]);return $u;}
 private function idea(?User $owner=null):Idea{return Idea::create(['title'=>'Farming','team'=>$owner?->name??'Applicant','initial'=>'','color'=>'#fff','ink'=>'#000','applicant_id'=>$owner?->id,'category'=>'Agriculture','location'=>'Private Village','submitted_at'=>now(),'programme_id'=>$this->pid(),'summary'=>'Grow food','problem'=>'Limited food','solution'=>'Grow crops','status'=>'ready','complete'=>100,'checks'=>[],'form_schema'=>FormCatalog::current($this->pid()),'form_version'=>'online-v2','form_answers'=>['business_stage'=>'Idea / concept','customers'=>'Local buyers','category_answers'=>['Agriculture'=>['activity'=>'Maize','resources'=>'Water','market'=>'Shops']]]]);}
 private function template():int{return DB::table('review_templates')->insertGetId(['programme_id'=>$this->pid(),'name'=>'Evaluation','kind'=>'evaluation','version'=>1,'criteria'=>'[]','active'=>true,'created_at'=>now(),'updated_at'=>now()]);}
 public function test_logout_with_request_receipt_does_not_read_cleared_user():void{$this->admin();$this->postJson('/api/v1/logout',[],['Idempotency-Key'=>(string)Str::uuid()])->assertNoContent();$this->getJson('/api/v1/me')->assertUnauthorized();}
 public function test_complete_online_submission_checks_allocation_without_account_verification():void{Queue::fake();$this->template();$e=$this->user();DB::table('reviewer_preferences')->insert(['user_id'=>$e->id,'programme_id'=>$this->pid(),'category'=>'Agriculture']);$owner=$this->user('Viewer');$owner->member_type='applicant';$owner->save();$this->actingAs($owner);$body=['programme_id'=>$this->pid(),'title'=>'New farm','category'=>'Agriculture','location'=>'Maun','summary'=>'Grow food','problem'=>'Food shortage','solution'=>'Grow crops','form_version'=>'online-v2','submit'=>true,'declaration'=>true,'form_answers'=>['business_stage'=>'Idea / concept','customers'=>'Local buyers','category_answers'=>['Agriculture'=>['activity'=>'Maize','resources'=>'Land','market'=>'Local shops','validation_plan'=>'Run a local pilot']]]];$headers=['Idempotency-Key'=>(string)Str::uuid()];$a=$this->postJson('/api/v1/applicant/applications',$body,$headers)->assertOk();$b=$this->postJson('/api/v1/applicant/applications',$body,$headers)->assertOk();$this->assertSame($a->json('data.id'),$b->json('data.id'));Queue::assertNotPushed(\App\Jobs\AllocateCompleteApplication::class);$this->assertDatabaseHas('review_assignments',['idea_id'=>$a->json('data.id'),'user_id'=>$e->id]);$this->assertDatabaseHas('portal_notifications',['idea_id'=>$a->json('data.id'),'user_id'=>$e->id,'kind'=>'review_assigned']);$owner->email_verified_at=null;$owner->save();$this->postJson('/api/v1/applicant/applications',$body)->assertOk();}
 public function test_reset_password_needs_a_new_per_action_authenticator_confirmation():void{Queue::fake();$this->admin();$target=$this->user();$this->patchJson('/api/v1/people/'.$target->id,['action'=>'reset_password'])->assertStatus(423);$this->withSession(['password_reset_confirmed_at'=>time()])->patchJson('/api/v1/people/'.$target->id,['action'=>'reset_password'])->assertOk();Queue::assertPushed(\App\Jobs\DeliverAccountCode::class,1);$this->patchJson('/api/v1/people/'.$target->id,['action'=>'reset_password'])->assertStatus(423);}
 public function test_programme_admin_cannot_remove_master_overrides_or_grant_admin_roles():void{$manager=$this->user('Programme Administrator');$target=$this->user();DB::table('access_overrides')->insert(['user_id'=>$target->id,'programme_id'=>$this->pid(),'permission'=>'reviews.evaluate','allowed'=>false]);$this->actingAs($manager)->withSession(['mfa_user_id'=>$manager->id,'mfa_verified_at'=>time()]);$this->patchJson('/api/v1/people/'.$target->id,['action'=>'access','programme_id'=>$this->pid(),'role_ids'=>[DB::table('roles')->where('name','Viewer')->value('id')]])->assertOk();$this->assertDatabaseHas('access_overrides',['user_id'=>$target->id,'permission'=>'reviews.evaluate','allowed'=>false]);$this->patchJson('/api/v1/people/'.$target->id,['action'=>'access','programme_id'=>$this->pid(),'role_ids'=>[DB::table('roles')->where('name','Programme Administrator')->value('id')]])->assertForbidden();}
 public function test_expired_codes_and_five_wrong_attempts_cannot_be_redeemed():void{Queue::fake();$service=new AccountChallenges;$u=$this->user();$id=$service->issue($u,'verify','email');$job=Queue::pushed(\App\Jobs\DeliverAccountCode::class)->last();for($n=0;$n<5;$n++)$this->assertFalse($service->redeem($id,'verify','000000',fn()=>null));$this->assertFalse($service->redeem($id,'verify',$job->code,fn()=>null));$id=$service->issue($this->user(),'verify','email');$job=Queue::pushed(\App\Jobs\DeliverAccountCode::class)->last();DB::table('account_challenges')->where('id',$id)->update(['expires_at'=>now()->subSecond()]);$this->assertFalse($service->redeem($id,'verify',$job->code,fn()=>null));}
 public function test_configured_email_queues_invites_and_never_returns_private_links():void{Queue::fake();config(['mail.default'=>'smtp']);$this->admin();$role=DB::table('roles')->where('name','Evaluator')->value('id');$this->postJson('/api/v1/people',['name'=>'Queued Reviewer','email'=>'queued@example.test','programme_id'=>$this->pid(),'role_ids'=>[$role],'type'=>'staff','mode'=>'invite'])->assertCreated()->assertJsonPath('delivery','queued')->assertJsonPath('activation_url',null);Queue::assertPushed(\App\Jobs\DeliverInvitation::class,1);$this->assertDatabaseHas('staff_invitations',['delivery_status'=>'queued']);}
 public function test_repeated_invitation_key_creates_one_account_and_one_invite():void{$this->admin();$headers=['Idempotency-Key'=>(string)Str::uuid()];$body=['name'=>'Invitee','email'=>'invitee@example.test','programme_id'=>$this->pid(),'role_ids'=>[DB::table('roles')->where('name','Evaluator')->value('id')],'type'=>'staff','mode'=>'invite'];$one=$this->postJson('/api/v1/people',$body,$headers)->assertCreated();$two=$this->postJson('/api/v1/people',$body,$headers)->assertCreated();$this->assertSame($one->json('data.id'),$two->json('data.id'));$this->assertDatabaseCount('staff_invitations',1);$this->postJson('/api/v1/people',[...$body,'email'=>'different@example.test'],$headers)->assertStatus(409);}
 public function test_bulk_invites_deduplicate_and_skip_existing_accounts():void{$u=$this->admin();$role=DB::table('roles')->where('name','Evaluator')->value('id');$this->postJson('/api/v1/people/bulk-invite',['emails'=>['one@example.test','one@example.test','bad',$u->email],'programme_id'=>$this->pid(),'role_ids'=>[$role],'type'=>'staff'])->assertOk()->assertJsonCount(3,'data');$this->assertDatabaseHas('users',['email'=>'one@example.test','account_status'=>'invited']);$this->assertDatabaseCount('staff_invitations',1);}
 public function test_published_forms_are_versioned_and_cannot_mutate_saved_drafts():void{$this->admin();$body=['stages'=>['Concept','Tested'],'categories'=>[['name'=>'Agriculture','description'=>'Farm','questions'=>[['key'=>'crop','label'=>'Which crop?','hint'=>'','required'=>true,'max'=>3000,'stages'=>['Tested']]]]]];$this->postJson('/api/v1/application-forms/'.$this->pid(),$body)->assertOk()->assertJsonPath('definition.mode','online');$first=FormCatalog::current($this->pid());$idea=$this->idea();$idea->form_schema=$first;$idea->save();$body['categories'][0]['questions'][0]['label']='Updated question';$this->postJson('/api/v1/application-forms/'.$this->pid(),$body)->assertOk();$this->assertNotSame($first['version'],FormCatalog::current($this->pid())['version']);$this->assertSame('Which crop?',$idea->fresh()->form_schema['categories']['Agriculture']['questions'][0]['label']);$body['categories'][0]['questions'][0]['stages']=['Unknown'];$this->postJson('/api/v1/application-forms/'.$this->pid(),$body)->assertStatus(422);}
 public function test_summary_preferences_assign_the_least_loaded_evaluator_and_retry_does_not_duplicate():void{$this->template();$a=$this->user();$b=$this->user();foreach([$a,$b] as $u)DB::table('reviewer_preferences')->insert(['user_id'=>$u->id,'programme_id'=>$this->pid(),'category'=>'Agriculture']);$allocator=new AutoAllocator;$first=$this->idea();$one=$allocator->assign($first->id);$this->assertContains($one,[$a->id,$b->id]);$this->assertNull($allocator->assign($first->id));$two=$allocator->assign($this->idea()->id);$this->assertNotSame($one,$two);$this->assertDatabaseCount('review_assignments',2);$this->assertDatabaseHas('review_assignments',['allocation_source'=>'preference']);$this->assertDatabaseCount('portal_notifications',2);}
 public function test_automatic_assignment_waits_for_completed_onboarding_and_single_template():void{$u=$this->user();$u->onboarding_completed_at=null;$u->save();$this->template();$i=$this->idea();$this->assertNull((new AutoAllocator)->assign($i->id));$this->assertSame('ready',$i->fresh()->status);$u->onboarding_completed_at=now();$u->save();$this->template();$this->assertNull((new AutoAllocator)->assign($i->id));}
 public function test_unmatched_business_goes_to_admin_and_mapping_change_routes_it():void{$admin=$this->admin();$this->artisan('ceda:publish-smart-form');$e=$this->user();$this->template();DB::table('reviewer_preferences')->insert(['user_id'=>$e->id,'programme_id'=>$this->pid(),'category'=>'Community services']);$idea=$this->idea();$idea->category='Poultry';$idea->save();$this->assertNull((new AutoAllocator)->assign($idea->id));$this->assertSame('ready',$idea->fresh()->status);$this->assertDatabaseHas('portal_notifications',['user_id'=>$admin->id,'idea_id'=>$idea->id,'kind'=>'allocation_needed']);$this->actingAs($admin)->withSession(['mfa_user_id'=>$admin->id,'mfa_verified_at'=>time()])->putJson('/api/v1/review-category-mappings/'.$this->pid(),['detailed_category'=>'Poultry','summary_category'=>'Community services'])->assertOk();$this->assertDatabaseHas('review_assignments',['idea_id'=>$idea->id,'user_id'=>$e->id]);$this->assertDatabaseHas('portal_notifications',['user_id'=>$e->id,'idea_id'=>$idea->id,'kind'=>'review_assigned']);$this->assertSame('Poultry',$idea->fresh()->category);}
 public function test_evaluator_onboarding_lists_only_five_summary_categories():void{$e=$this->user();$e->onboarding_completed_at=null;$e->save();$this->actingAs($e)->withSession(['mfa_user_id'=>$e->id]);$data=$this->getJson('/api/v1/reviewer-preferences')->assertOk()->json('programmes.0.categories');$this->assertSame(['Agriculture','Manufacturing','Retail and trade','ICT and digital','Community services'],$data);$this->putJson('/api/v1/reviewer-preferences',['preferences'=>[['programme_id'=>$this->pid(),'category'=>'Poultry']]])->assertUnprocessable();$this->putJson('/api/v1/reviewer-preferences',['preferences'=>[['programme_id'=>$this->pid(),'category'=>'Agriculture']]])->assertOk();$this->putJson('/api/v1/reviewer-preferences',['preferences'=>[['programme_id'=>$this->pid(),'category'=>'Manufacturing']]])->assertForbidden();}
 public function test_assignment_notification_is_private_and_can_be_read():void{$this->template();$e=$this->user();DB::table('reviewer_preferences')->insert(['user_id'=>$e->id,'programme_id'=>$this->pid(),'category'=>'Agriculture']);$idea=$this->idea();(new AutoAllocator)->assign($idea->id);$this->actingAs($e)->withSession(['mfa_user_id'=>$e->id]);$notification=$this->getJson('/api/v1/notifications')->assertOk()->assertJsonPath('unread',1)->json('data.0.id');$other=$this->user();$this->actingAs($other)->withSession(['mfa_user_id'=>$other->id])->postJson('/api/v1/notifications/'.$notification.'/read')->assertNotFound();$this->actingAs($e)->withSession(['mfa_user_id'=>$e->id])->postJson('/api/v1/notifications/'.$notification.'/read')->assertOk();$this->getJson('/api/v1/notifications')->assertJsonPath('unread',0);}
 public function test_account_codes_are_single_use_and_attempt_limited():void{Queue::fake();$u=$this->user();$service=new AccountChallenges;$id=$service->issue($u,'reset','email');Queue::assertPushed(\App\Jobs\DeliverAccountCode::class);$job=Queue::pushed(\App\Jobs\DeliverAccountCode::class)->first();$this->assertFalse($service->redeem($id,'reset','000000',fn()=>null));$this->assertTrue($service->redeem($id,'reset',$job->code,fn($user)=>null));$this->assertFalse($service->redeem($id,'reset',$job->code,fn()=>null));}
 public function test_summary_requires_assigned_evaluator_and_sends_no_known_identifiers():void{config(['portal.ai_key'=>'test-key']);Http::fake(['api.openai.com/*'=>Http::response(['output'=>[['content'=>[['type'=>'output_text','text'=>'Problem: Limited food [problem]']]]]])]);$owner=$this->user('Viewer');$owner->member_type='applicant';$owner->save();$i=$this->idea($owner);$i->summary='Contact '.$owner->name.' at '.$owner->email.' or +267 71234567.';$i->save();$e=$this->user();DB::table('reviewer_preferences')->insert(['user_id'=>$e->id,'programme_id'=>$this->pid(),'category'=>'Agriculture']);$this->template();$this->assertSame($e->id,(new AutoAllocator)->assign($i->id));$this->actingAs($e)->withSession(['mfa_user_id'=>$e->id]);$preview=$this->getJson('/api/v1/applications/'.$i->id.'/summary-preview')->assertOk()->json();$this->postJson('/api/v1/applications/'.$i->id.'/summary',[...$preview,'privacy_confirmed'=>true])->assertOk();Http::assertSent(fn($r)=>!str_contains($r['input'],$owner->email)&&!str_contains($r['input'],'Jane')&&!str_contains($r['input'],'71234567')&&$r['store']===false);$this->actingAs($owner)->getJson('/api/v1/applications/'.$i->id.'/summary-preview')->assertForbidden();}
 public function test_public_assistant_handles_missing_guidance_without_account_access():void{$this->postJson('/api/v1/chat/ask',['question'=>'How do I apply?'])->assertOk()->assertJsonFragment(['mode'=>'document_guidance','confidence'=>'low']);$this->postJson('/api/v1/chat/ask',['question'=>str_repeat('x',1001)])->assertStatus(422);}
}
